mapper.select:
SELECT

FROM RUNNING_SHOES
WHERE shoe_id = #{shoeId} AND runner_id = #{runnerId}

mapper.update:
UPDATE RUNNING_SHOES
SET is_default = TRUE, updated_at = CURRENT_TIMESTAMP
WHERE shoe_id = #{shoeId} AND runner_id = #{runnerId}

UPDATE RUNNING_SHOES
SET is_retired = TRUE, is_default = FALSE, updated_at = CURRENT_TIMESTAMP
WHERE shoe_id = #{shoeId} AND runner_id = #{runnerId}

mapper.select:
SELECT COALESCE(SUM(distance_km), 0.0)
FROM RUN_RECORD
WHERE runner_id = #{runnerId}

    AND run_date >= #{purchasedDate}
